import { NotFoundError, ValidationError } from "@/lib/db/errors";
import { getPrisma } from "@/lib/db/prisma";
import { validateIdempotencyKey } from "@/lib/db/orders";

/**
 * Idempotency-Key is a random 122+ bit capability generated by the checkout
 * browser. Pair it with the guest's exact normalized email; NEVER accept
 * an order number alone and NEVER expose address, products or customer PII.
 * Real order detail remains protected by the email OTP tracking workflow.
 */
export function validateCheckoutRecoveryRequest(raw: unknown) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw))
    throw new ValidationError("Invalid checkout recovery request.");
  const body = raw as Record<string, unknown>;
  const key = validateIdempotencyKey(typeof body.key === "string" ? body.key : "");
  const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
  if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
    throw new ValidationError("A valid checkout email is required.");
  return { key, email };
}

export type CheckoutRecoveryResult = {
  orderNumber: string;
  paymentMethod: string | null;
  paymentStatus: string;
  status: string;
};

/** Read-only lookup: no guest-user creation, reservations, email or payment. */
export async function recoverCompletedCheckoutAttempt(raw: { key: string; email: string }):
  Promise<CheckoutRecoveryResult> {
  const { key, email } = validateCheckoutRecoveryRequest(raw);
  const prisma = getPrisma();
  const user = await prisma.user.findUnique({
    where: { email }, select: { id: true },
  });
  const notFound = () => new NotFoundError("No completed order matches this checkout attempt.");
  if (!user) throw notFound();
  const attempt = await prisma.checkoutAttempt.findUnique({
    where: { userId_key: { userId: user.id, key } },
    select: { orderId: true },
  });
  if (!attempt?.orderId) throw notFound();
  const order = await prisma.order.findFirst({
    where: { id: attempt.orderId, userId: user.id },
    select: { orderNumber: true, paymentMethod: true, paymentStatus: true, status: true },
  });
  if (!order) throw notFound();
  return order;
}
